SELECT id, user_id, user_name, user_department_id, user_department_name,
       group_id, group_name, group_type, group_sub_type, group_create_type,
       gmt_create_time, group_updated_time
FROM tb_static_create_group
WHERE gmt_create_time >= #{startTime} AND gmt_create_time < #{endTime}

    AND user_department_id IN

        #{deptId}



    AND (gmt_create_time < #{lastTime} OR (gmt_create_time = #{lastTime} AND id < #{lastId}))

ORDER BY gmt_create_time DESC, id DESC
LIMIT #{pageSize}
